"use client";

import { motion, useInView } from "motion/react";
import { useId, useRef, useState, useSyncExternalStore, type ReactNode } from "react";

// Five animated cards of the MCP shelf (agent workflows, tool calls, multi-tool,
// OAuth, connect). Static geometry is the captured rest state; every looping
// motion below carries the source timings verbatim.

const easeInOutCubic = (e: number) => (e < 0.5 ? 4 * e * e * e : 1 - (-2 * e + 2) ** 3 / 2);
const INF = Infinity;

const dashBack = (duration: number) => ({
  strokeDashoffset: ["0%", "-100%"],
  transition: { duration, ease: "linear" as const, repeat: INF },
});
const dashFwd = (duration: number) => ({
  strokeDashoffset: ["0%", "100%"],
  transition: { duration, ease: "linear" as const, repeat: INF },
});

const noopSubscribe = () => () => {};
const useUid = () => useId().replace(/:/g, "");

type CardProps = { className: string };

/* ---------- 01 agent workflows ---------- */
const CYCLE = { duration: 5, ease: easeInOutCubic, repeat: INF };
const cycle = (opacity: number[]) => ({
  animate: { opacity, transition: CYCLE },
  initial: { opacity: 0 },
});

