/* ---------- 02 tool calls ---------- */
const randOffset = () => 15 * Math.random() - 7.5;
const randDuration = () => 2 * Math.random() + 2;
const makeTarget = () => ({ d: randDuration(), x: randOffset(), y: randOffset() });

function Drift({ className, children }: { className: string; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref);
  // Random first target, like the source (never part of the server markup: it only applies once in view).
  const [target, setTarget] = useState(makeTarget);
  return (
    <motion.div
      ref={ref}
      className={className}
      animate={inView ? { x: target.x, y: target.y } : undefined}
      transition={{ duration: target.d, ease: "easeInOut" }}
      onAnimationComplete={() => setTarget(makeTarget())}
    >
      {children}
    </motion.div>
  );
}

export function McpToolCalls({ className }: CardProps) {
  return (
    <div className={className}>
        <img alt="" width="1746" height="882" decoding="async" data-nimg="1" className="mask-l-from-50% mask-b-from-50% mask-b-to-85% size-full object-contain" style={{"color":"transparent"}} srcSet="/img/img-1bd6c2b921.png 1x, /img/img-1bd6c2b921.png 2x" src="/img/img-1bd6c2b921.png" />
        <Drift className="absolute top-1/2 left-1/6 w-[27.26526718%]">
          <img alt="" width="274" height="94" decoding="async" data-nimg="1" style={{"color":"transparent"}} srcSet="/img/img-8680c10390.png 1x, /img/img-8680c10390.png 2x" src="/img/img-8680c10390.png" />
        </Drift>
        <Drift className="absolute top-[45%] right-[8%] w-[21.18320611%]">
          <img alt="" width="210" height="92" decoding="async" data-nimg="1" style={{"color":"transparent"}} srcSet="/img/img-286930eff6.png 1x, /img/img-286930eff6.png 2x" src="/img/img-286930eff6.png" />
        </Drift>
    </div>
  );
}

/* ---------- 03 multi-tool ---------- */
const TOOL_STAGGER = 4 / 3;
const toolPulse = (e: number, t: number, peak: number) => ({
  animate: { opacity: [0, peak, 0] },
  initial: { opacity: 0 },
  transition: {
    opacity: {
      delay: e * TOOL_STAGGER + 0.12 * t,
      duration: 2,
      ease: easeInOutCubic,
      repeat: INF,
      repeatDelay: 2,
      times: [0, 0.25, 1],
    },
  },
});

